  ('renter_driving_notice', 'renter', '{}'::text[], 'transactional', false, null, 'CarmaCars <bookings@carmacars.ca>', 'bookings@carmacars.ca', '{{event_title}}: your {{vehicle_name}}', '{{event_short}}', 'Immediate, once per event', 'Tracker events are on (migration 3320) and the Tracker of a car out on this renter''s rental recorded driving worth a friendly word, with no charge: a speed over the speeding alert level of Tracking settings (140 km/h by default) but not over 180 km/h, or several hard braking or acceleration events in the window. Once per event (one per car, kind and window). The renter may mute it in their notification settings.', null, '/account/bookings/{{booking_number}}', '[{"name":"booking_number","type":"string"},{"name":"company_address","type":"string","global":true},{"name":"contact_email","type":"string","global":true},{"name":"event_ask","type":"string"},{"name":"event_clause","type":"string"},{"name":"event_fee","type":"string"},{"name":"event_short","type":"string"},{"name":"event_title","type":"string"},{"name":"event_what","type":"string"},{"name":"event_when","type":"string"},{"name":"first_name","type":"string"},{"name":"instagram_url","type":"url","global":true},{"name":"opening_hours","type":"string","global":true},{"name":"reply_time","type":"string","global":true},{"name":"support_phone","type":"string","global":true},{"name":"tiktok_url","type":"url","global":true},{"name":"vehicle_name","type":"string"}]'::jsonb, 'templates/renter_driving_notice.html', 'templates/renter_driving_notice.txt'),
  ('owner_tracker_alert', 'owner', '{}'::text[], 'transactional', false, null, 'CarmaCars <owners@carmacars.ca>', 'owners@carmacars.ca', '{{event_title}}: your {{vehicle_name}}', '{{event_short}}', 'Immediate, once per event', 'Tracker events are on (migration 3320) and the Tracker of one of this owner''s cars recorded an event: speeding, harsh driving, the car outside Ontario or the zone, driving after the return time or at night, the Tracker unplugged or tampered with, or the car parked at an impound lot. The event, the time and the place only: never the renter or the booking. Once per event (one per car, kind and window). The owner may mute it in their notification settings.', null, '/owner/vehicles/{{vehicle_id}}', '[{"name":"company_address","type":"string","global":true},{"name":"contact_email","type":"string","global":true},{"name":"event_map_url","type":"url"},{"name":"event_short","type":"string"},{"name":"event_title","type":"string"},{"name":"event_what","type":"string"},{"name":"event_when","type":"string"},{"name":"first_name","type":"string"},{"name":"instagram_url","type":"url","global":true},{"name":"opening_hours","type":"string","global":true},{"name":"reply_time","type":"string","global":true},{"name":"support_phone","type":"string","global":true},{"name":"tiktok_url","type":"url","global":true},{"name":"vehicle_id","type":"string"},{"name":"vehicle_name","type":"string"}]'::jsonb, 'templates/owner_tracker_alert.html', 'templates/owner_tracker_alert.txt'),
  ('staff_pound_flag', 'staff_va_fleet', array['staff_admin']::text[], 'transactional', false, null, 'CarmaCars <bookings@carmacars.ca>', 'contact@carmacars.ca', 'AT A POUND: {{car_label}} at {{lot_name}}', '{{booking_line}}. Parked since {{pound_since}}.', 'Immediate, once per stay at a lot', 'Tracker events are on (migration 3320) and a car''s Tracker shows it parked inside the radius of a known impound or pound lot (Admin > Cars > Fleet tracking > Pound lots) for the minutes set in Tracking settings. The booking is flagged, Fleet gets an urgent To do and alert, and this email. Once per car, lot and stay.', null, '/staff/fleet/map', '[{"name":"booking_line","type":"string"},{"name":"car_label","type":"string"},{"name":"company_address","type":"string","global":true},{"name":"lot_address","type":"string"},{"name":"lot_hours","type":"string"},{"name":"lot_name","type":"string"},{"name":"lot_phone","type":"string"},{"name":"non_return_fee","type":"string"},{"name":"pound_since","type":"string"},{"name":"theft_recovery_fee","type":"string"}]'::jsonb, 'templates/staff_pound_flag.html', 'templates/staff_pound_flag.txt')
