select app.notification_catalogue_refresh();
-- CATALOGUE 3321 END
update notification_catalogue set push_topic = 'alerts', hold_to_merge = false, priority = 1, emitted_by = 'app.tracker_alert_after (3320): a tracker event while Tracker events are on'
 where code in ('renter_tracker_notice', 'renter_driving_notice');
update notification_catalogue set push_topic = 'alerts', hold_to_merge = false, priority = 2, user_can_mute = true, emitted_by = 'app.tracker_alert_after (3320): a tracker event of the owner''s car'
 where code = 'owner_tracker_alert';
update notification_catalogue set user_can_mute = true where code = 'renter_driving_notice';
update notification_catalogue set always_send = true where code = 'renter_tracker_notice';
update notification_catalogue set push_topic = 'alerts', hold_to_merge = false, priority = 3, emitted_by = 'app.tracker_pound_scan (3320): a car parked at a known pound'
 where code = 'staff_pound_flag';

-- a text where it fits: the same words as the notice's first line; the charge or breach notice is urgent (sent at once, at night too)
insert into sms_templates (code, label, body, enabled, urgent, sort_order) values
  ('renter_tracker_notice', 'Tracker notice (a charge or the agreement)', 'CarmaCars: {{event_title}}. {{event_short}} Details: {{link}}', true, true, coalesce((select max(sort_order) + 1 from sms_templates), 1)),
  ('renter_driving_notice', 'Driving heads-up (no charge)', 'CarmaCars: {{event_title}}. {{event_short}} Details: {{link}}', true, false, coalesce((select max(sort_order) + 2 from sms_templates), 2)),
  ('owner_tracker_alert', 'Tracker alert (owner)', 'CarmaCars: {{event_title}}. {{event_short}} Details: {{link}}', true, false, coalesce((select max(sort_order) + 3 from sms_templates), 3))
on conflict (code) do nothing;

-- a car at a pound is urgent: its email goes at once, not in the staff digest (0583)
alter function app.staff_email_urgent(text, uuid, timestamptz) rename to staff_email_urgent_pre3321;
create function app.staff_email_urgent(p_code text, p_booking uuid, p_now timestamptz default now()) returns boolean
language sql stable security definer set search_path = public, app as $$
  select p_code = 'staff_pound_flag' or app.staff_email_urgent_pre3321(p_code, p_booking, p_now)
$$;
revoke all on function app.staff_email_urgent(text, uuid, timestamptz), app.staff_email_urgent_pre3321(text, uuid, timestamptz) from public, anon, authenticated;
grant execute on function app.staff_email_urgent(text, uuid, timestamptz), app.staff_email_urgent_pre3321(text, uuid, timestamptz) to service_role;

-- the pound email's button (emails/src/links.mjs, va_fleet_tracking)
insert into notification_link_paths (key, path) values ('va_fleet_tracking', '/staff/fleet/map') on conflict (key) do update set path = excluded.path;

-- each new kind's staff notice has its switch (staff_alert_rules, 3320), read where 0462 reads the others: a rule turned
-- off makes no staff notice (in-app, push or the pound email) for its kind
alter function app.notification_recipients(app_events, notification_catalogue) rename to notification_recipients_pre3321;
create function app.notification_recipients(p_event app_events, p_c notification_catalogue)
returns table (audience text, user_id uuid, email text, name text, renter_id uuid, owner_id uuid, immediate boolean)
language plpgsql stable security definer set search_path = public, app as $$
begin
  if p_c.code in ('staff_tracker_alert', 'staff_tracker_alert_fleet', 'staff_pound_flag') and exists (
       select 1 from staff_alert_rules r
        where not r.enabled and r.rule = case coalesce(p_event.payload ->> 'alert_kind', case when p_c.code = 'staff_pound_flag' then 'pound' end)
                when 'pound' then 'tracker_pound' when 'tamper' then 'tracker_tamper' when 'harsh_driving' then 'tracker_harsh' when 'after_hours' then 'tracker_night' end) then
    return;
  end if;
  return query select * from app.notification_recipients_pre3321(p_event, p_c);
end $$;
do $$
declare g text;
begin
  execute 'revoke all on function app.notification_recipients(app_events, notification_catalogue), app.notification_recipients_pre3321(app_events, notification_catalogue) from public, anon, authenticated';
  foreach g in array array['anon', 'authenticated', 'service_role'] loop
    if has_function_privilege(g, 'app.notification_recipients_pre3321(app_events, notification_catalogue)'::regprocedure, 'execute') then
      execute format('grant execute on function app.notification_recipients(app_events, notification_catalogue) to %I', g);
    end if;
  end loop;
end $$;
